import { FC } from 'react';
import { Link, LinkProps } from 'react-router-dom';

import { Flex, Typography } from 'antd';
import cn from 'classnames';

import AngleRightIcon from 'assets/images/icons/angle-right.svg?react';

import styles from './DashboardLink.module.scss';

interface IDashboardLinkProps extends LinkProps {
	to: string;
}

export const DashboardLink: FC<IDashboardLinkProps> = ({ className, to, children, ...props }) => {
	return (
		<Link {...props} to={to} className={cn(className, styles.link)}>
			<Flex align="center" justify="space-between" gap={12}>
				{children}
				<Typography.Text type="secondary">
					<AngleRightIcon />
				</Typography.Text>
			</Flex>
		</Link>
	);
};
